<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import UiIcon from './UiIcon.vue'

const props = defineProps<{ method: any; progress?: { bestScore: number | null; attempts: number } }>()
const emit = defineEmits<{ back: []; quiz: [] }>()
const activeIndex = ref(0)
const principles = computed<string[]>(() => props.method.overview.principles)
const stages = computed<Array<{ id: string; label: string; subtitle: string; description: string; example: string }>>(() => props.method.stages)
const applicationSteps = computed<string[]>(() => props.method.application.steps)
const activeStage = computed(() => props.method.stages[activeIndex.value] ?? props.method.stages[0])
watch(() => props.method.id, () => { activeIndex.value = 0 })
function scrollToStages() { document.getElementById('lesson-stages')?.scrollIntoView({ behavior: 'smooth' }) }
</script>

<template>
  <div class="lesson" :style="{ '--lesson-accent': method.accent }">
    <button class="lesson-back" type="button" @click="emit('back')"><UiIcon name="left" :size="17" /> До каталогу методик</button>
    <section class="lesson-hero"><div class="lesson-hero-grid"></div><div class="lesson-hero-copy"><span class="lesson-eyebrow"><span></span> ІНТЕРАКТИВНИЙ МАТЕРІАЛ / {{ method.category.toUpperCase() }}</span><h1>{{ method.title }}</h1><p>{{ method.summary }}</p><div class="lesson-meta"><span><UiIcon name="book" :size="16" /> {{ method.author }}</span><span><UiIcon name="clock" :size="16" /> {{ method.estimatedMinutes }} хв читання</span><span><UiIcon name="layers" :size="16" /> {{ method.stages.length }} рівнів / етапів</span></div></div><div class="lesson-hero-art" aria-hidden="true"><div class="lesson-art-ring lesson-art-ring--outer"></div><div class="lesson-art-ring lesson-art-ring--inner"></div><div class="lesson-art-center"><strong>{{ String(method.stages.length).padStart(2, '0') }}</strong><span>ЕТАПІВ</span></div><span class="lesson-art-dot dot-a"></span><span class="lesson-art-dot dot-b"></span><span class="lesson-art-dot dot-c"></span></div></section>

    <div class="lesson-layout"><div class="lesson-main-column">
      <section class="lesson-section"><div class="lesson-section-head"><span class="section-number">01 / КОНЦЕПЦІЯ</span><h2>Ідея та призначення</h2><p>Наукове підґрунтя методики й те, як її застосовують у навчанні.</p></div><div class="overview-grid"><div class="overview-card"><div class="overview-icon"><UiIcon name="sparkle" :size="20" /></div><h3>Походження</h3><p>{{ method.overview.origin }}</p></div><div class="overview-card"><div class="overview-icon"><UiIcon name="target" :size="20" /></div><h3>Для чого застосовують</h3><p>{{ method.overview.purpose }}</p></div></div></section>

      <section class="lesson-section principles-section"><div class="lesson-section-head"><span class="section-number">02 / ОСНОВНІ ПРИНЦИПИ</span><h2>Що важливо пам’ятати</h2><p>Ключові орієнтири для коректного використання концепції.</p></div><div class="principle-list"><div v-for="(principle, index) in principles" :key="index" class="principle-item"><span class="principle-index">{{ String(index + 1).padStart(2, '0') }}</span><p>{{ principle }}</p></div></div><div v-if="method.overview.caveat" class="lesson-note"><UiIcon name="info" :size="19" /><p>{{ method.overview.caveat }}</p></div></section>

      <section id="lesson-stages" class="lesson-section stages-section"><div class="lesson-section-head"><span class="section-number">03 / ІНТЕРАКТИВНА СХЕМА</span><h2>Як працює методика</h2><p>Оберіть рівень або крок, щоб побачити його зміст і приклад.</p></div><div class="stage-explorer"><div class="stage-list" role="tablist" aria-label="Етапи методики"><button v-for="(stage, index) in stages" :key="stage.id" type="button" class="stage-tab" :class="{ 'stage-tab--active': activeIndex === index }" role="tab" :aria-selected="activeIndex === index" :aria-controls="'stage-panel'" @click="activeIndex = index"><span class="stage-tab-index">{{ String(index + 1).padStart(2, '0') }}</span><span class="stage-tab-copy"><strong>{{ stage.label }}</strong><small>{{ stage.subtitle }}</small></span><UiIcon name="chevron" :size="17" /></button></div><div id="stage-panel" class="stage-detail" role="tabpanel" :key="activeStage.id"><div class="stage-detail-grid"></div><div class="stage-detail-top"><span>ЕТАП {{ String(activeIndex + 1).padStart(2, '0') }} / {{ String(method.stages.length).padStart(2, '0') }}</span><span class="stage-detail-icon"><UiIcon name="sparkle" :size="25" /></span></div><div><div class="stage-detail-orbit"><span>{{ String(activeIndex + 1).padStart(2, '0') }}</span></div><h3>{{ activeStage.label }}</h3><strong class="stage-subtitle">{{ activeStage.subtitle }}</strong><p>{{ activeStage.description }}</p><div class="stage-example"><span>ПРИКЛАД ІЗ ПРАКТИКИ</span><p>{{ activeStage.example }}</p></div></div><div class="stage-detail-footer"><span>ДОСЛІДЖУЙТЕ КОЖЕН КРОК</span><span>{{ activeIndex + 1 }} / {{ method.stages.length }}</span></div></div></div></section>

      <section class="lesson-section application-section"><div class="lesson-section-head"><span class="section-number">04 / ЗАСТОСУВАННЯ</span><h2>Методика в дії</h2><p>Як ця методика організовує навчання на темі «{{ method.quest.topic }}».</p></div><div class="application-card"><div class="application-heading"><span class="application-icon"><UiIcon name="play" :size="19" /></span><div><span>СЦЕНАРІЙ ВЕБКВЕСТУ</span><h3>{{ method.application.title }}</h3></div></div><p class="application-scenario">{{ method.application.scenario }}</p><div class="application-steps"><div v-for="(step, index) in applicationSteps" :key="index" class="application-step"><span>{{ String(index + 1).padStart(2, '0') }}</span><p>{{ step }}</p></div></div><div class="application-outcome"><UiIcon name="check" :size="19" /><p><strong>Результат.</strong> {{ method.application.outcome }}</p></div></div></section>

      <section v-if="method.sources?.length" class="lesson-section sources-section"><div class="lesson-section-head"><span class="section-number">05 / ДЖЕРЕЛА</span><h2>Для глибшого читання</h2></div><div class="sources-list"><a v-for="source in method.sources" :key="source.url" :href="source.url" target="_blank" rel="noopener noreferrer"><UiIcon name="book" :size="18" /><span>{{ source.label }}</span><UiIcon name="arrow" :size="16" /></a></div></section>

      <section class="test-cta"><div><span class="lesson-eyebrow"><span></span> НАСТУПНИЙ КРОК</span><h2>{{ method.quest.mission }}</h2><p>{{ method.quest.strategy }} Завдання присвячені темі «{{ method.quest.topic }}».</p><button type="button" class="btn btn-primary" @click="emit('quiz')">Почати вебквест <UiIcon name="arrow" :size="18" /></button></div><div class="test-cta-visual" aria-hidden="true"><UiIcon name="target" :size="94" /><span>QUEST / {{ String(method.quest.stages.length).padStart(2, '0') }}</span></div></section>
    </div><aside class="lesson-aside"><div class="lesson-aside-card"><span class="aside-title">ЗМІСТ МАТЕРІАЛУ</span><a href="#" @click.prevent="scrollToStages"><span>01</span> Інтерактивна схема <UiIcon name="chevron" :size="15" /></a><div class="aside-divider"></div><span class="aside-title">ВАШ ПРОГРЕС</span><div class="aside-progress"><strong>{{ progress?.bestScore ?? 0 }}%</strong><span>найкращий результат</span></div><div class="aside-progress-track"><span :style="{ width: `${progress?.bestScore ?? 0}%` }"></span></div><p>Завершено проходжень: {{ progress?.attempts ?? 0 }}</p><button type="button" class="aside-test-button" @click="emit('quiz')">Почати вебквест <UiIcon name="arrow" :size="16" /></button></div></aside></div>
  </div>
</template>

